types/gather.ts 생성:

// 열거형 타입
export type EventStatus = 'upcoming' | 'ongoing' | 'ended'
export type ParticipantRole = 'host' | 'participant'
export type UserRole = 'user' | 'admin'

// 엔티티 타입
export interface GatherUser { id, email, name, avatarUrl, role: UserRole, createdAt }
export interface GatherEvent { id, title, description, location, eventDate, coverImageUrl, inviteCode, status: EventStatus, createdBy, participantCount, createdAt, updatedAt }
export interface GatherParticipant { id, eventId, userId, role: ParticipantRole, joinedAt, user?: GatherUser }

// 관리자 통계 타입
export interface AdminStats { todayEvents, weekEvents, monthEvents, totalEvents, todayUsers, weekUsers, totalUsers }

// 폼 입력값 타입
export interface EventFormValues { title, description, location, eventDate, coverImage?: File }

// 컴포넌트 Props 타입
export interface EventCardProps { event: GatherEvent, onClick?: () => void }
export interface ParticipantCardProps { participant: GatherParticipant }

